raiz=Path(__file__).resolve().parent
assert (raiz/'.git').exists()
rastreados=set(subprocess.check_output(['git','ls-files'],cwd=raiz,text=True).splitlines())
assert rastreados <= set(BASE)|{'publicar_estudiantes.py','.github/workflows/asignar.yml'}, 'Archivos ajenos detectados'
originales={}
for nombre,expected in BASE.items():
    ruta=(raiz/nombre).resolve()
    assert ruta.is_relative_to(raiz) and ruta.is_file(),nombre
    b=ruta.read_bytes()
    assert hashlib.sha256(b).hexdigest()==expected, 'Archivo cambió: '+nombre
    originales[nombre]=b
nuevos={nombre:originales[anterior] for nombre,anterior in RECURSOS.items()}
nuevos.update({nombre:texto.encode('utf-8') for nombre,texto in TEXTOS.items()})
assert set(nuevos)==set(FINAL)
for nombre,b in nuevos.items():
    assert hashlib.sha256(b).hexdigest()==FINAL[nombre],nombre
    if nombre.endswith('.py'):ast.parse(b.decode('utf-8'),filename=nombre)
for nombre in BASE:
    ruta=(raiz/nombre).resolve()
    assert ruta.is_relative_to(raiz)
    ruta.unlink()
for nombre,b in nuevos.items():
    ruta=(raiz/nombre).resolve()
    assert ruta.is_relative_to(raiz)
    ruta.parent.mkdir(parents=True,exist_ok=True)
    ruta.write_bytes(b)
# Retirar únicamente carpetas de casos antiguas que hayan quedado vacías.
for ruta in sorted((raiz/'casos').rglob('*'),key=lambda x:len(x.parts),reverse=True):
    if ruta.is_dir() and not any(ruta.iterdir()):ruta.rmdir()
(raiz/'publicar_estudiantes.py').unlink()
print(json.dumps({'archivos':len(nuevos),'estudiantes':8,'caso_reserva':7}))
